def _detect_line_ending(source: IO[str]) -> str:
    """Return the first LF or CRLF line-ending style found in the stream.

    The stream is rewound afterwards so it can be consumed normally.
    Defaults to LF when no line ending is present.
    """
    source.seek(0)
    data = source.read()
    source.seek(0)
    if "\r\n" in data:
        return "\r\n"
    if "\n" in data:
        return "\n"
    return "\n"

